  "legend": "<b>Dust Levels Legend:</b><br><div style=\"background: linear-gradient(to bottom,#00FF00, #33FF33, #66FF66, #99FF99, #FFFF00, #FFA500, #FF0000); height: 162px; width: 20px; margin-right: 10px; display: inline-block;\"></div><div style=\"display: inline-block; vertical-align: top;\"><div>0</div><div>50</div><div>100</div><div>150</div><div>200</div><div>250</div><div>300+</div></div>"
};

return msg;

    // Initialize an object to store grouped data
    var groupedData = {};

    // Iterate over each incoming message
    for (var i = 0; i < msg.payload.length; i++) {
        var data = msg.payload[i];

        if (!groupedData[data.ssid]) {
            // If not, initialize an array for the 'area' property
            groupedData[data.ssid] = {
                area: [],
                dataTime: "",
                temperature: 0,
                humidity: 0,
                dustDensity: 0,
                color: "" ,
                centerLat: 0,
                centerLon: 0,
                "fillOpacity": 0.8,
            };
        }

        // Add the lat and lon to the 'area' array
        groupedData[data.ssid].area.push([data.lat, data.lon]);

        // Update other properties
        groupedData[data.ssid].dataTime = data.Data_Time;

        // Add up values for later calculation of mean
        groupedData[data.ssid].temperature += data.temperature;
        groupedData[data.ssid].humidity += data.humidity;
        groupedData[data.ssid].dustDensity += data.dustDensity;
    }

    // Calculate the mean values
    for (var ssid in groupedData) {
        if (groupedData.hasOwnProperty(ssid)) {
            var numItems = groupedData[ssid].area.length;
            groupedData[ssid].temperature /= numItems;
            groupedData[ssid].humidity /= numItems;
            groupedData[ssid].dustDensity /= numItems;


   var sumLat = 0;
        var sumLon = 0;

        for (var j = 0; j < numItems; j++) {
            sumLat += groupedData[ssid].area[j][0];
            sumLon += groupedData[ssid].area[j][1];
        }

        groupedData[ssid].centerLat = sumLat / numItems;
         groupedData[ssid].centerLon = sumLon / numItems;

            // Calculate color based on linear gradient
            var dustDensity = groupedData[ssid].dustDensity;
            if (dustDensity < 50) {
                groupedData[ssid].color = "#00FF00";
            } else if (dustDensity < 100) {
                groupedData[ssid].color = "#33FF33";
            } else if (dustDensity < 150) {
                groupedData[ssid].color = "#66FF66";
            } else if (dustDensity < 200) {
                groupedData[ssid].color = "#99FF99";
            } else if (dustDensity < 250) {
                groupedData[ssid].color = "#FFFF00"; 
            } else if (dustDensity < 300) {
                groupedData[ssid].color = "#FFA500"; 
            } else {
                groupedData[ssid].color = "#FF0000"; 
            }
        }
    }

    // Convert the groupedData object into an array
    var result = [];
    for (var ssid in groupedData) {
        if (groupedData.hasOwnProperty(ssid)) {
            groupedData[ssid].ssid = ssid;
            result.push(groupedData[ssid]);


  var locationData = {
    name: ssid,
    area: groupedData[ssid].area,
    color: groupedData[ssid].color,
    fillColor: groupedData[ssid].color,
    lat: groupedData[ssid].centerLat,
    lon: groupedData[ssid].centerLon,
    data: 
    {
        temperature: groupedData[ssid].temperature,
        humidity: groupedData[ssid].humidity,
        dustDensity: groupedData[ssid].dustDensity
    }
};


              node.send({
            payload: locationData,
            topic: "worldmap"
        });
        }
    }

    // Update the payload with the result
    msg.payload = result;

    return msg;
